cd /workspace && python3 - <<'PYEOF'
import json,subprocess,sys,tempfile
from pathlib import Path
sys.path.insert(0,'/workspace')
from tmp.run_check import execute
cases=json.loads(Path('/workspace/examples/fixtures.json').read_text())
with tempfile.TemporaryDirectory() as tmp:
    tmp=Path(tmp); root=tmp/'root'; root.mkdir()
    (root/'deps').symlink_to(Path('/workspace/deps'),target_is_directory=True)
    sub=root/'submission'
    subprocess.run(['cp','-r','/workspace/submission',str(sub)],check=True)
    work=tmp/'w'; work.mkdir()
    case=cases[1]
    out,err,code=execute(sub/'campaign.py',json.dumps(case['input']).encode(),work)
    mine=json.loads(out); exp=case['expected']
    def diff(a,b,path=''):
        if type(a)!=type(b):
            print('TYPE',path,type(a),type(b)); return
        if isinstance(a,dict):
            for k in set(a)|set(b):
                if k not in a: print('MISSING in mine',path+'/'+k)
                elif k not in b: print('EXTRA in mine',path+'/'+k)
                else: diff(a[k],b[k],path+'/'+k)
        elif isinstance(a,list):
            if len(a)!=len(b): print('LEN',path,len(a),len(b))
            for i,(x,y) in enumerate(zip(a,b)): diff(x,y,path+f'[{i}]')
        elif a!=b: print('VALUE',path,repr(a),repr(b))
    diff(mine,exp)
PYEOF
